int main(int argc,char**argv){@autoreleasepool{
 if(argc!=2)return 2;NSString*out=@(argv[1]);[[NSFileManager defaultManager]createDirectoryAtPath:out withIntermediateDirectories:YES attributes:nil error:NULL];
 NSString*source=@"#include <metal_stdlib>\nusing namespace metal;kernel void extra(device const ushort*p[[buffer(0)]],device half*q[[buffer(1)]],uint i[[thread_position_in_grid]]){half a=as_type<half>(p[i]);half nz=as_type<half>(ushort(0x8000));uint k=i*8;q[k]=atan2(a,half(0));q[k+1]=atan2(half(0),a);q[k+2]=atan2(a,nz);q[k+3]=atan2(nz,a);q[k+4]=exp(a);q[k+5]=log(a);q[k+6]=pow(a,half(.5f));q[k+7]=pow(a,half(1));}\nkernel void pairs(device const half2*p[[buffer(0)]],device half*q[[buffer(1)]],uint i[[thread_position_in_grid]]){q[i]=atan2(p[i].x,p[i].y);}\n";
 id<MTLDevice>d=MTLCreateSystemDefaultDevice();NSError*error=nil;MTLCompileOptions*o=[MTLCompileOptions new];o.fastMathEnabled=YES;id<MTLLibrary>l=[d newLibraryWithSource:source options:o error:&error];if(!l){[error.description writeToFile:[out stringByAppendingPathComponent:@"error.txt"]atomically:YES encoding:NSUTF8StringEncoding error:NULL];return 3;}id<MTLCommandQueue>queue=[d newCommandQueue];
 for(NSString*name in @[@"extra",@"pairs"]){NSUInteger n=[name isEqualToString:@"extra"]?65536:262144,cols=[name isEqualToString:@"extra"]?8:1,inputCols=[name isEqualToString:@"extra"]?1:2;NSMutableData*input=[NSMutableData dataWithLength:n*inputCols*2];uint16_t*p=input.mutableBytes;uint32_t state=2026101808u;
  for(NSUInteger i=0;i<n*inputCols;i++){if(inputCols==1)p[i]=(uint16_t)i;else{state=1664525u*state+1013904223u;uint16_t bits=(uint16_t)(state>>8);if((bits&0x7c00)==0x7c00)bits=(uint16_t)((bits&0x83ff)|0x7800);p[i]=bits;}}
  id<MTLComputePipelineState>ps=[d newComputePipelineStateWithFunction:[l newFunctionWithName:name]error:&error];if(!ps)return 4;id<MTLBuffer>ib=[d newBufferWithBytes:input.bytes length:input.length options:MTLResourceStorageModeShared],ob=[d newBufferWithLength:n*cols*2 options:MTLResourceStorageModeShared];id<MTLCommandBuffer>cb=[queue commandBuffer];id<MTLComputeCommandEncoder>e=[cb computeCommandEncoder];[e setComputePipelineState:ps];[e setBuffer:ib offset:0 atIndex:0];[e setBuffer:ob offset:0 atIndex:1];[e dispatchThreads:MTLSizeMake(n,1,1)threadsPerThreadgroup:MTLSizeMake(128,1,1)];[e endEncoding];[cb commit];[cb waitUntilCompleted];if(cb.error)return 5;
  [input writeToFile:[out stringByAppendingPathComponent:[name stringByAppendingString:@"-input.f16"]]atomically:YES];[[NSData dataWithBytes:ob.contents length:ob.length]writeToFile:[out stringByAppendingPathComponent:[name stringByAppendingString:@"-output.f16"]]atomically:YES];
 }
 NSDictionary*m=@{@"source":source,@"os":NSProcessInfo.processInfo.operatingSystemVersionString,@"device":d.name,@"extra_shape":@[@65536,@8],@"extra_columns":@[@"atan2(a,+0)",@"atan2(+0,a)",@"atan2(a,-0)",@"atan2(-0,a)",@"exp(a)",@"log(a)",@"pow(a,.5)",@"pow(a,1)"],@"pairs_shape":@[@262144,@2],@"pairs_seed":@2026101808,@"pairs_domain":@"Finite raw half bits, signed normal/subnormal/zero; exponent31 mapped to30"};[[NSJSONSerialization dataWithJSONObject:m options:NSJSONWritingPrettyPrinted error:NULL]writeToFile:[out stringByAppendingPathComponent:@"metadata.json"]atomically:YES];return 0;
